//! 🧪️ Portable octet cases keep exact backing and refused prefixes under original recipients.
use super::*;
use semio_framework_value::native_encoding::{OriginalConstructionRecipient,OriginalConstructionGrant,OriginalConstructionGrantComplete,OriginalConstructionAccept,OriginalConstructionAcceptComplete,OriginalConstructionAuthority,OriginalWorkRecipient,OriginalWorkQuote,OriginalWorkQuoteComplete,OriginalWorkAuthority,OriginalWorkPartialCheck,OriginalWorkPartialCheckComplete,OriginalSourceTurnIdentity};
struct Work{remaining:u64}
impl OriginalWorkRecipient for Work{
 type Context<'turn,'source>=() where 'source:'turn;
 fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError>where 'source:'turn{Ok(())}
 fn source_turn<'turn,'source>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn admits<'reply,'turn,'source>(&mut self,_:&mut (),quote:OriginalWorkQuote<'reply>,observed:u64,additional:u64)->OriginalWorkQuoteComplete<'reply>where 'source:'turn{quote.complete(Ok(observed.checked_add(additional).is_some_and(|total|total<=self.remaining)))}
 fn settle_partial<'reply,'turn,'source>(&mut self,context:&mut (),check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{check.complete(self.validate_context(context))}
 fn recover_partial<'reply,'turn,'source>(&mut self,context:&mut (),check:OriginalWorkPartialCheck<'reply>)->OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{check.complete(self.validate_context(context))}
}
struct Recipient{grant:RetainedCloneGrant,submitted:RetainedCloneProgress,refuse_copy:bool,quoted:Option<RetainedCloneGrant>}
impl OriginalConstructionRecipient for Recipient{
 type Context<'turn,'source>=() where 'source:'turn;
 fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError>where 'source:'turn{Ok(())}
 fn source_turn<'turn,'source>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 'source:'turn{None}
 fn submitted<'turn,'source>(&self,_:&())->RetainedCloneProgress where 'source:'turn{self.submitted}
 fn grant<'a,'turn,'source>(&mut self,_:&mut (),quote:OriginalConstructionGrant<'a>)->OriginalConstructionGrantComplete<'a>where 'source:'turn{self.quoted=Some(self.grant);quote.complete(Ok(self.grant))}
 fn accept<'a,'turn,'source>(&mut self,_:&mut (),receipt:OriginalConstructionAccept<'a>)->OriginalConstructionAcceptComplete<'a>where 'source:'turn{let progress=receipt.progress();assert_eq!(Some(receipt.grant()),self.quoted.take());let result=self.submitted.checked_add(progress).map(|total|self.submitted=total).and_then(|_|if self.refuse_copy&&progress.retained_capacity_bytes==0{Err(ValueError::literal(ValueRefusalKind::Canceled,"original blob receipt refused"))}else{Ok(())});receipt.complete(result)}
}
#[test]
fn encoded_octets_keep_original_backing_prefix_and_receipt(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let count=fixture["payloadBytes"].as_u64().unwrap()as usize;let pattern=fixture["pattern"].as_array().unwrap();let input:Vec<u8>=(0..count).map(|i|pattern[i%pattern.len()].as_u64().unwrap()as u8).collect();
 for case in fixture["cases"].as_array().unwrap(){
  let grant=RetainedCloneGrant{maximum_items:8,maximum_copy_bytes:count+size_of::<Vec<u8>>(),maximum_capacity_bytes:count,maximum_release_bytes:count,maximum_depth:4};
  let recipient=Recipient{grant,submitted:Default::default(),refuse_copy:case["name"]=="first-copy-receipt",quoted:None};let mut work=Work{remaining:if case["name"]=="before-allocation"{0}else{8}};
  let mut callback=|_|true;let mut native=NativeEncodeControl::new(count,&mut callback);let mut body=NativeSnapshotBodyWallet::new(grant);let mut output=Vec::new();let mut marker=NativeSnapshotEffectProgress::default();let mut unwind=None;let mut allocation_state=crate::NativeSnapshotEncodeAllocation::default();
  let mut construction=OriginalConstructionAuthority::new(recipient);let mut work_authority=OriginalWorkAuthority::new(work);let result=construction.with_loan(&mut (),|construction_loan|work_authority.with_loan(&mut (),|work_loan|native.with_construction_recipient(construction_loan,|native|native.with_work_recipient(work_loan,|native|Ok::<_,ValueError>(body.copy_bytes_encoded(native,&input,&mut output,&mut marker,&mut unwind,&mut allocation_state,1)))))).unwrap().unwrap().unwrap();let submitted=construction.inspect(|recipient|recipient.submitted);
  assert_eq!(result.result.is_err(),case["refused"].as_bool().unwrap());assert_eq!(output.len(),case["retained"].as_u64().unwrap()as usize);assert_eq!(output,&input[..output.len()]);assert_eq!(native.actual_work(),u128::from(case["work"].as_u64().unwrap()));assert_eq!(result.work,native.actual_work());if native.actual_work()==0{assert_eq!(native.owned_bytes(),0);}assert_eq!(submitted,body.progress());assert!(unwind.is_none());
  assert_eq!(output.capacity(),if native.actual_work()==0{0}else{count});assert_eq!(serde_json::to_value(&output).unwrap(),serde_json::from_slice::<serde_json::Value>(&serde_json::to_vec(&input[..output.len()]).unwrap()).unwrap());
  let close_grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:256};
  close(output,close_grant);allocation_state.state.settle_claimed_work().unwrap();close(allocation_state,close_grant);if let Err(failure)=result.result{close(failure,close_grant);}
 }
}

fn close<T:semio_framework_value::retirement::RetireOwned>(value:T,grant:RetainedCloneGrant){let mut owner=semio_framework_value::retirement::controlled::ControlledRetirement::new(value).map_err(|(error,_)|error).unwrap();let mut bank=semio_framework_value_testing_admission::EffectBank::new(semio_framework_value_testing_admission::BankWallet::new(grant,1<<40));for _ in 0..4096{if owner.terminal_is_empty(){break}let turn=bank.run_outcome(grant,1<<20,|effect|{let mut turn=None;semio_framework_value_control_contract::with_original_invocation(None,effect,&mut |effect|turn=Some(match owner.step(65536,effect){semio_framework_value::RetainedWorkPoll::Complete(turn)=>turn,semio_framework_value::RetainedWorkPoll::Pending{..}=>panic!("fixture close stayed pending")})).unwrap();turn.unwrap()});turn.result.unwrap();bank.take_admitted();}assert!(owner.terminal_is_empty());}

#[test]
fn refused_exact_backing_records_performed_zero_in_original_allocation(){
 let bytes=4*size_of::<u64>();let grant=RetainedCloneGrant{maximum_items:4,maximum_copy_bytes:128,maximum_capacity_bytes:bytes,maximum_release_bytes:bytes,maximum_depth:4};let recipient=Recipient{grant,submitted:Default::default(),refuse_copy:false,quoted:None};let work=Work{remaining:4};let mut callback=|_|true;let mut native=NativeEncodeControl::new(bytes,&mut callback);let mut output=None;let mut marker=NativeSnapshotEffectProgress::default();let mut unwind=None;let mut allocation=crate::NativeSnapshotEncodeAllocation::default();let mut construction=OriginalConstructionAuthority::new(recipient);let mut work_authority=OriginalWorkAuthority::new(work);
 let((turn,refused),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_trace_memory_testing::refuse_one_allocation_on_this_thread(||construction.with_loan(&mut (),|construction_loan|work_authority.with_loan(&mut (),|work_loan|native.with_construction_recipient(construction_loan,|native|native.with_work_recipient(work_loan,|native|{let mut owner=crate::NativeSnapshotEncodeOwner::new(native,grant);Ok::<_,ValueError>(owner.allocate_vector::<u64>(4,&mut output,&mut marker,&mut unwind,&mut allocation,1))})))).unwrap().unwrap().unwrap()));let submitted=construction.inspect(|recipient|recipient.submitted);assert_eq!(refused,1);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(turn.work,1);assert!(output.is_none());let failure=turn.result.unwrap_err();let effect=failure.encode_effect().expect("original encoder effect failure");assert_eq!(effect.primary.as_ref().unwrap().kind,ValueRefusalKind::AllocationFailed);assert_eq!(allocation.state.actual,Some(0));assert_eq!(submitted.retained_capacity_bytes,0);assert_eq!(native.actual_work(),1);assert!(unwind.is_none());let close_grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};allocation.state.settle_claimed_work().unwrap();close(allocation,close_grant);close(failure,close_grant);
}

#[test]
fn refused_decode_backing_records_performed_zero_in_original_allocation(){
 use semio_framework_value_native_owned::native_decoding::NativeDecodeControl;
 let bytes=4*size_of::<u64>();let grant=RetainedCloneGrant{maximum_items:4,maximum_copy_bytes:128,maximum_capacity_bytes:bytes,maximum_release_bytes:bytes,maximum_depth:4};let recipient=Recipient{grant,submitted:Default::default(),refuse_copy:false,quoted:None};let work=Work{remaining:4};let mut callback=|_|true;let mut native=NativeDecodeControl::new(bytes,&mut callback);let mut output=None;let mut marker=NativeSnapshotEffectProgress::default();let mut unwind=None;let mut allocation=crate::NativeSnapshotDecodeAllocation::default();let mut construction=OriginalConstructionAuthority::new(recipient);let mut work_authority=OriginalWorkAuthority::new(work);
 let((turn,refused),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_trace_memory_testing::refuse_one_allocation_on_this_thread(||construction.with_loan(&mut (),|construction_loan|work_authority.with_loan(&mut (),|work_loan|native.with_construction_recipient(construction_loan,|native|native.with_work_recipient(work_loan,|native|{let mut owner=crate::NativeSnapshotDecodeOwner::new(native,grant);Ok::<_,ValueError>(owner.allocate_vector::<u64>(4,&mut output,&mut marker,&mut unwind,&mut allocation,1))})))).unwrap().unwrap().unwrap()));let submitted=construction.inspect(|recipient|recipient.submitted);assert_eq!(refused,1);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(turn.work,1);assert!(output.is_none());let failure=turn.result.unwrap_err();let Some(crate::NativeSnapshotAllocationFailure::Decode(outcome))=failure.allocation() else{panic!("original decode allocation outcome missing")};assert_eq!(outcome.actual,Some(0));assert_eq!(allocation.actual,Some(0));assert_eq!(submitted.retained_capacity_bytes,0);assert_eq!(native.actual_work(),1);assert!(unwind.is_none());let close_grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};close(allocation,close_grant);close(failure,close_grant);
}

#[test]fn refused_octet_copy_records_performed_zero_before_any_output(){let input=[1u8,2,3,4];let grant=RetainedCloneGrant{maximum_items:4,maximum_copy_bytes:128,maximum_capacity_bytes:input.len(),maximum_release_bytes:input.len(),maximum_depth:4};let recipient=Recipient{grant,submitted:Default::default(),refuse_copy:false,quoted:None};let work=Work{remaining:4};let mut callback=|_|true;let mut native=NativeEncodeControl::new(input.len(),&mut callback);let mut body=NativeSnapshotBodyWallet::new(grant);let mut output=Vec::new();let mut marker=NativeSnapshotEffectProgress::default();let mut unwind=None;let mut allocation=crate::NativeSnapshotEncodeAllocation::default();let mut construction=OriginalConstructionAuthority::new(recipient);let mut work_authority=OriginalWorkAuthority::new(work);let((turn,refused),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||semio_framework_trace_memory_testing::refuse_one_allocation_on_this_thread(||construction.with_loan(&mut (),|construction_loan|work_authority.with_loan(&mut (),|work_loan|native.with_construction_recipient(construction_loan,|native|native.with_work_recipient(work_loan,|native|Ok::<_,ValueError>(body.copy_bytes_encoded(native,&input,&mut output,&mut marker,&mut unwind,&mut allocation,1)))))).unwrap().unwrap().unwrap()));let submitted=construction.inspect(|recipient|recipient.submitted);assert_eq!(refused,1);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(turn.work,1);assert!(output.is_empty()&&output.capacity()==0);let failure=turn.result.unwrap_err();let effect=failure.encode_effect().expect("original encoder effect failure");assert_eq!(effect.primary.as_ref().unwrap().kind,ValueRefusalKind::AllocationFailed);assert_eq!(allocation.state.actual,Some(0));assert_eq!(submitted.retained_capacity_bytes,0);assert_eq!(native.actual_work(),1);assert!(unwind.is_none());let close_grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};close(output,close_grant);allocation.state.settle_claimed_work().unwrap();close(allocation,close_grant);close(failure,close_grant);}
